// 扩写句子: the sentence is shown as word blocks with gaps between them. The player picks a gap, then a word
// card; the word is written above a 增补号 (∧) at that gap, as in 修改病句. Several gaps can be filled; the
// expanded sentence must equal one of q.answers (generated by tools/banks.py from q.slots).
(() => {
  'use strict';
  const { el, button, shuffle } = PK;
  const INSERT = '<path d="M9 51L19 39L29 51 M19 39V17H42"/><rect x="42" y="7" width="42" height="20" rx="10"/>';
  const CARET = '<svg class="expand-caret" viewBox="0 0 40 30" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 27L20 4L35 27"/></svg>';

  function built(q, a) {
    return q.tokens.map((t, i) => (a.ins[i] || '') + t).join('') + (a.ins[q.tokens.length] || '');
  }
  const used = a => Object.values(a.ins);

  function render(q, a, ctx) {
    const wrap = el('div', 'q-expand');
    const tools = el('div', 'symbol-tray');
    const symbol = el('span', 'symbol-button selected');
    symbol.innerHTML = `<svg viewBox="0 0 90 58" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" preserveAspectRatio="none">${INSERT}</svg><span>增补号</span>`;
    symbol.setAttribute('role', 'img');
    symbol.setAttribute('aria-label', '增补号');
    tools.append(symbol);
    const need = q.slots.length, have = used(a).length;
    const hint = ctx.locked ? '' : a.gap === null
      ? `点句子中的短线，再选要添的词语。至少扩写${need}处（已扩写${have}处）。`
      : '选一张词卡，添到这个位置；点上面已添的词可以去掉。';
    wrap.append(tools, el('p', 'edit-hint', hint));

    const board = el('div', 'edit-board expand-board');
    const gap = i => {
      const holder = el('span', 'gap-wrap');
      if (a.ins[i]) {
        holder.classList.add('filled');
        const word = button(a.ins[i], () => ctx.change(s => {
          delete s.ins[i];
          s.gap = null;
        }), 'expand-word');
        word.setAttribute('aria-label', `去掉添加的“${a.ins[i]}”`);
        word.disabled = ctx.locked;
        holder.append(word);
        holder.insertAdjacentHTML('beforeend', CARET);
      } else {
        const b = button('', () => ctx.change(s => (s.gap = s.gap === i ? null : i)), 'gap insertable' + (a.gap === i ? ' selected' : ''));
        b.setAttribute('aria-label', i === 0 ? '在句首添词' : `在“${q.tokens[i - 1]}”后面添词`);
        b.disabled = ctx.locked;
        holder.append(b);
      }
      board.append(holder);
    };
    q.tokens.forEach((token, i) => {
      gap(i);
      const holder = el('span', 'word-wrap');
      holder.append(el('span', 'word', token));
      board.append(holder);
    });
    wrap.append(board);

    if (a.gap !== null && !ctx.locked) {
      const cards = el('div', 'word-cards');
      cards.setAttribute('aria-label', '可用词语');
      const taken = used(a);
      for (const value of ctx.view.cards) {
        const b = button(value, () => ctx.change(s => {
          s.ins[s.gap] = value;
          s.gap = null;
        }), 'word-card');
        b.disabled = taken.includes(value);
        cards.append(b);
      }
      wrap.append(cards);
    }
    wrap.append(el('p', 'preview', '扩写后：' + built(q, a)));
    return wrap;
  }

  PK.register('expand', {
    init(q, ctx) {
      ctx.view.cards = shuffle(q.cards);
      return { ins: {}, gap: null };
    },
    render,
    value(q, a) {
      const have = used(a).length, need = q.slots.length;
      if (have < need) return { incomplete: `至少要扩写${need}处，现在只扩写了${have}处。` };
      return { value: built(q, a) };
    },
    check: (q, value) => q.answers.includes(value),
    solution: q => q.answers[0],
    describe: q => `扩写：${q.base}`,
  });
})();
